#include <cstdio>
#include <stdexcept>

class File {
    std::FILE* f_;                     // the raw resource
public:
    explicit File(const char* path) : f_(std::fopen(path, "w")) {
        if (f_ == nullptr) throw std::runtime_error("open failed");
    }
    ~File() { if (f_ != nullptr) std::fclose(f_); }   // always runs

    File(const File&) = delete;             // one owner, no aliasing
    File& operator=(const File&) = delete;

    void write(const char* s) { std::fputs(s, f_); }
};

int main() {
    File log("session.log");       // acquired
    log.write("order submitted\n");
}                                   // fclose runs here - on every exit path

#include <iostream>
#include <stdexcept>

struct Marker {
    const char* n;
    explicit Marker(const char* name) : n(name) { std::cout << "acq " << n << '\n'; }
    ~Marker() { std::cout << "rel " << n << '\n'; }
};

void risky() {
    Marker m("in risky");
    throw std::runtime_error("feed down");
}

int main() {
    try {
        risky();
    } catch (const std::exception& e) {
        std::cout << "caught: " << e.what() << '\n';
    }
}
// acq in risky
// rel in risky      <- destructor ran during unwinding, before the catch
// caught: feed down

